WITH pattern_union_r AS (
SELECT 'Actor' AS start_type, toString(db_denorm_selfloop.events.src_actor) as start_id, toString(db_denorm_selfloop.events.dst_actor) as end_id, 'Actor' AS end_type, ['RECEIVED'] as path_relationships, [formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.channel AS channel, db_denorm_selfloop.events.evt_id AS evt_id)] as rel_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.src_actor AS _s_src_actor, db_denorm_selfloop.events.src_name AS _s_src_name) as start_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.dst_actor AS _e_dst_actor, db_denorm_selfloop.events.dst_name AS _e_dst_name) as end_properties, db_denorm_selfloop.events.channel AS channel, db_denorm_selfloop.events.evt_id AS evt_id, NULL AS weight FROM db_denorm_selfloop.events
UNION ALL
SELECT 'Actor' AS start_type, toString(db_denorm_selfloop.events.dst_actor) as start_id, toString(db_denorm_selfloop.events.src_actor) as end_id, 'Actor' AS end_type, ['RECEIVED'] as path_relationships, [formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.channel AS channel, db_denorm_selfloop.events.evt_id AS evt_id)] as rel_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.dst_actor AS _s_dst_actor, db_denorm_selfloop.events.dst_name AS _s_dst_name) as start_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.src_actor AS _e_src_actor, db_denorm_selfloop.events.src_name AS _e_src_name) as end_properties, db_denorm_selfloop.events.channel AS channel, db_denorm_selfloop.events.evt_id AS evt_id, NULL AS weight FROM db_denorm_selfloop.events WHERE (db_denorm_selfloop.events.dst_actor != db_denorm_selfloop.events.src_actor)
UNION ALL
SELECT 'Actor' AS start_type, toString(db_denorm_selfloop.events.src_actor) as start_id, toString(db_denorm_selfloop.events.dst_actor) as end_id, 'Actor' AS end_type, ['SENT'] as path_relationships, [formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.evt_id AS evt_id, db_denorm_selfloop.events.weight AS weight)] as rel_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.src_actor AS _s_src_actor, db_denorm_selfloop.events.src_name AS _s_src_name) as start_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.dst_actor AS _e_dst_actor, db_denorm_selfloop.events.dst_name AS _e_dst_name) as end_properties, NULL AS channel, db_denorm_selfloop.events.evt_id AS evt_id, db_denorm_selfloop.events.weight AS weight FROM db_denorm_selfloop.events
UNION ALL
SELECT 'Actor' AS start_type, toString(db_denorm_selfloop.events.dst_actor) as start_id, toString(db_denorm_selfloop.events.src_actor) as end_id, 'Actor' AS end_type, ['SENT'] as path_relationships, [formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.evt_id AS evt_id, db_denorm_selfloop.events.weight AS weight)] as rel_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.dst_actor AS _s_dst_actor, db_denorm_selfloop.events.dst_name AS _s_dst_name) as start_properties, formatRowNoNewline('JSONEachRow', db_denorm_selfloop.events.src_actor AS _e_src_actor, db_denorm_selfloop.events.src_name AS _e_src_name) as end_properties, NULL AS channel, db_denorm_selfloop.events.evt_id AS evt_id, db_denorm_selfloop.events.weight AS weight FROM db_denorm_selfloop.events WHERE (db_denorm_selfloop.events.src_actor != db_denorm_selfloop.events.dst_actor)
)
SELECT 
      JSONExtractString(r.start_properties, '_s_src_name') AS "a.name", 
      JSONExtractString(r.end_properties, '_e_dst_name') AS "b.name"
FROM pattern_union_r AS r
